/**
 * @fileoverview Progressive-web-app glue.
 *
 * The service worker is intentionally tiny and is generated by build/pwa.py:
 * it precaches every game, language pack, image and sound so that a tablet
 * can install the site and keep playing without a network.  This file only
 * registers it and offers the browser's install prompt as a normal button.
 */
'use strict';

(function() {
  if (!('serviceWorker' in navigator) ||
      (location.protocol !== 'https:' && location.protocol !== 'http:')) {
    return;
  }

  window.addEventListener('load', function() {
    navigator.serviceWorker.register('sw.js').catch(function(error) {
      // A missing sw.js is normal when the folder is opened from file:// or
      // when the site is served by a host that does not allow service workers.
      console.warn('Service worker registration failed:', error);
    });
  });

  let deferredPrompt = null;

  /**
   * Add an install button to the page toolbar, or to the document when the
   * page has no toolbar.
   */
  function showInstallButton() {
    if (document.getElementById('installButton')) {
      return;
    }
    const button = document.createElement('button');
    button.id = 'installButton';
    button.type = 'button';
    button.className = 'installButton';
    button.textContent = (window['BlocklyGames'] &&
        window['BlocklyGames']['getMsg']) ?
        window['BlocklyGames']['getMsg']('Games.install', false) :
        'Install app';
    const host = document.getElementById('headerControls') ||
        document.getElementById('header_cta');
    if (host) {
      host.appendChild(button);
    } else {
      button.classList.add('installButtonFixed');
      document.body.appendChild(button);
    }
    button.addEventListener('click', function() {
      if (!deferredPrompt) {
        return;
      }
      deferredPrompt.prompt();
      deferredPrompt.userChoice.then(function() {
        deferredPrompt = null;
        button.remove();
      });
    }, false);
  }

  window.addEventListener('beforeinstallprompt', function(event) {
    event.preventDefault();
    deferredPrompt = event;
    showInstallButton();
  });

  // A game replaces document.body during startup.  If the prompt arrived
  // before that, put the button back once the real toolbar exists.
  window.addEventListener('load', function() {
    if (deferredPrompt) {
      showInstallButton();
    }
  });

  window.addEventListener('appinstalled', function() {
    const button = document.getElementById('installButton');
    if (button) {
      button.remove();
    }
    deferredPrompt = null;
  });
})();
